use rbn_core::{report::{Report,page},stats::{self,Throughput},retry};
use serde_json::{Value,json};
use std::fs;
fn normalized(v:&Value)->Value{match v{Value::Number(n) if n.as_f64().is_some_and(|x|x.abs()<=9_007_199_254_740_992.)=>json!(n.as_f64().unwrap()),Value::Array(a)=>Value::Array(a.iter().map(normalized).collect()),Value::Object(o)=>Value::Object(o.iter().map(|(k,v)|(k.clone(),normalized(v))).collect()),_=>v.clone()}}
fn check_bits(value:&Value,bits:&Value){for(path,expected)in bits.as_object().expect("Swift numeric bit patterns"){let actual=value.pointer(path).and_then(Value::as_f64).unwrap_or_else(||panic!("missing numeric field {path}"));assert_eq!(format!("{:016x}",actual.to_bits()),expected.as_str().unwrap(),"Swift pre-serialization bits at {path}");}}
fn fixture()->Value{serde_json::from_str(include_str!("fixtures/engine-0.11.0.json")).unwrap()}
#[test]fn swift_throughput_frames_and_finish_match(){for case in fixture()["throughput"].as_array().unwrap(){let mut meter=Throughput::default();meter.start_at(case["startAt"].as_f64().unwrap());let mut previous=stats::empty();for(i,frame)in case["frames"].as_array().unwrap().iter().enumerate(){let actual=meter.update_at(&frame["raw"],&previous,frame["at"].as_f64().unwrap());check_bits(&actual,&case["expectedBits"][i]);assert_eq!(normalized(&actual),normalized(&case["expected"][i]),"{} frame {i}",case["name"]);previous=actual;}let done=meter.finish_at(&previous,case["completed"].as_bool().unwrap(),case["finishAt"].as_f64().unwrap());check_bits(&done,&case["finishedBits"]);assert_eq!(normalized(&done),normalized(&case["finished"]),"{} finish",case["name"]);}}
#[test]fn swift_retry_accumulation_matches(){for c in fixture()["accumulation"].as_array().unwrap(){let actual=retry::accumulate(&c["raw"],&c["base"],c["carried"].as_u64().unwrap() as usize);assert_eq!(normalized(&actual),normalized(&c["expected"]));}}
#[test]fn swift_report_events_summaries_categories_and_raw_match(){let extra:Value=serde_json::from_str(include_str!("fixtures/raw-rclone-0.11.0.json")).unwrap();let base=fixture();for case in base["reports"].as_array().unwrap().iter().chain(extra["reports"].as_array().unwrap().iter()){let root=std::env::temp_dir().join(format!("rbn-golden-report-{}",uuid::Uuid::new_v4()));fs::create_dir_all(&root).unwrap();let id=uuid::Uuid::new_v4().to_string();let mut r=Report::new(&root,&id).unwrap();for(i,step)in case["steps"].as_array().unwrap().iter().enumerate(){match step["op"].as_str().unwrap(){"consume"=>r.consume(&step["value"],step["dry"].as_bool().unwrap_or(false)).unwrap(),"comparison"=>r.comparison_line(step["line"].as_str().unwrap(),step["terminated"].as_bool().unwrap()).unwrap(),"retry"=>r.retry_note(step["message"].as_str().unwrap(),step["attempt"].as_u64().unwrap() as usize,step["files"].as_u64().map(|n|n as usize)).unwrap(),"cleanup"=>r.directory_deleted(step["path"].as_str().unwrap(),step["dry"].as_bool().unwrap()).unwrap(),"poll"=>r.poll(step["final"].as_bool().unwrap()).unwrap(),op=>panic!("unknown fixture op {op}")};assert_eq!(normalized(&r.summary()),normalized(&case["summaries"][i]),"{} step {i}",case["name"]);}r.flush().unwrap();for(category,expected)in case["categories"].as_object().unwrap(){let response=page(&root,&id,&json!({"category":category,"limit":200}),Value::Null).unwrap();let mut actual=response["items"].as_array().unwrap().clone();for item in &mut actual{item.as_object_mut().unwrap().remove("time");}assert_eq!(normalized(&json!(actual)),normalized(expected),"{} category {category}",case["name"]);}assert_eq!(fs::read_to_string(root.join(format!("{id}.comparison.log"))).unwrap(),case["comparisonText"].as_str().unwrap());drop(r);fs::remove_dir_all(root).unwrap();}}
